<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { api } from '../api'
const list=ref<any[]>([]),loading=ref(false),result=ref<any>(); const form=reactive({summary_type:'annual',start_year:new Date().getFullYear(),end_year:new Date().getFullYear(),category:'',instructions:''})
async function load(){list.value=(await api.get('/ai-summaries')).data}
async function generate(){loading.value=true;try{result.value=(await api.post('/ai-summaries/generate',form)).data;ElMessage.success('总结已保存')}catch(e:any){ElMessage.error(e.response?.data?.detail||'生成失败')}finally{loading.value=false}}
onMounted(load)
</script>
<template><div class="ai-layout"><div class="panel"><p class="eyebrow">FACT-GROUNDED GENERATION</p><h3>依据真实成果生成总结</h3><el-alert type="success" :closable="false" title="AI 只接收已录入的真实成果，不得补充不存在的事实。"/><el-form label-position="top" style="margin-top:18px"><el-form-item label="总结类型"><el-select v-model="form.summary_type"><el-option label="年度成果总结" value="annual"/><el-option label="职称业绩总结" value="title"/><el-option label="分类成果总结" value="category"/></el-select></el-form-item><div class="grid-2"><el-form-item label="开始年度"><el-input-number v-model="form.start_year"/></el-form-item><el-form-item label="结束年度"><el-input-number v-model="form.end_year"/></el-form-item></div><el-form-item label="指定类别"><el-input v-model="form.category"/></el-form-item><el-form-item label="写作要求"><el-input v-model="form.instructions" type="textarea"/></el-form-item><el-button type="primary" :loading="loading" @click="generate">生成并保存新版本</el-button></el-form></div><div class="panel"><h3>生成结果</h3><div v-if="result" class="summary-text">{{result.edited_content||result.generated_content}}</div><div v-else class="empty">选择范围后生成总结。</div></div><div class="panel history"><h3>历史记录</h3><el-table :data="list" @row-click="(x:any)=>result=x"><el-table-column prop="summary_type" label="类型"/><el-table-column prop="start_year" label="开始年度"/><el-table-column prop="end_year" label="结束年度"/><el-table-column prop="created_at" label="创建时间"/></el-table></div></div></template>